    "--@@GATE-BEGIN\n"
    "-- ===== TURBO PER-PLAYER FACE GATE v4 (Turbo-owned, plain Lua; generated by Turbo core/faces3d.cpp) =====\n"
    "-- entries[playerid] = { hair = <id>|-1, beard = <id>|-1, hf = <fallback hair id>, bf = <fallback beard id>, hc = <bool>, bc = <bool> }\n"
    "--   fixed  : hair / beard are baked generic model ids (exactly as gate v2)\n"
    "--   follow : hair / beard = -1: the id is initData.Hair / initData.FacialHairType (the DB codes) when that code is >= 1,\n"
    "--            HairStyle == 0 and the code is on okHair / okBeard (verified generic 3D models, _1_0); otherwise hf / bf;\n"
    "--            otherwise nil (that part takes the stock path)\n"
    "--   hair  : loadHair / loadStrandHair take the generic path (head class 1) with the resolved hair id; hc = hair, eyebrow and\n"
    "--           facial-hair colours from the DB (generic branch)\n"
    "--   beard : loadPlayerBeard takes the generic 3D beard path with the resolved model; on a HeadClass 0 head it also replaces\n"
    "--           the scanned strand beard with the generic strand beard; bc = beard colours from the DB (HeadClass 0)\n"
    "--   band  : (v4) a real face (HeadClass 0, HairStyle 0) whose hairtypecode is HB + i takes generic hair bandHair[i], whose\n"
    "--           facialhairtypecode is BB + i takes generic beard bandBeard[i]; hc = bc = true; wins over entries[]; written live\n"
    "--           by Turbo in the DB, so a change shows at the next model build without a restart\n"
    "-- Switches: TURBO_GATE.enabled = false, or the global TURBO_FACES_GATE_OFF = true (before players load).\n"
    "local TURBO_GATE = {\n"
    "\tenabled = true,\n"
    "\tDB = -1,\n"
    "\t-- allow-lists: sorted inclusive ranges {lo1, hi1, lo2, hi2, ...}\n"
    "\tokHair = {\n"
    "--@@OKHAIR@@\n"
    "\t},\n"
    "\tokBeard = {\n"
    "--@@OKBEARD@@\n"
    "\t},\n"
    "\tentries = {\n"
    "--@@ENTRIES@@\n"
    "\t},\n"
    "\t-- v4 bands: FROZEN append-only lists (index = position)\n"
    "\tHB = 8039,\n"
    "\tBB = 335,\n"
    "\tbandHair = {\n"
    "--@@BANDHAIR@@\n"
    "\t},\n"
    "\tbandBeard = {\n"
    "--@@BANDBEARD@@\n"
    "\t},\n"
    "\tbandMemo = {},\n"
    "}\n"
    "TURBO_GATE.band = function(initData)\n"
    "\tif type(initData) ~= \"table\" then return nil end\n"
    "\tif rawget(initData, \"HeadClass\") ~= 0 or rawget(initData, \"HairStyle\") ~= 0 then return nil end\n"
    "\tlocal h, b = rawget(initData, \"Hair\"), rawget(initData, \"FacialHairType\")\n"
    "\tlocal hid = type(h) == \"number\" and TURBO_GATE.bandHair[h - TURBO_GATE.HB] or nil\n"
    "\tlocal bid = type(b) == \"number\" and TURBO_GATE.bandBeard[b - TURBO_GATE.BB] or nil\n"
    "\tif hid == nil and bid == nil then return nil end\n"
    "\tlocal k = (hid or 0) * 4096 + (bid or 0)\n"
    "\tlocal e = TURBO_GATE.bandMemo[k]\n"
    "\tif e == nil then\n"
    "\t\te = { hair = hid, beard = bid, hc = true, bc = true }\n"
    "\t\tTURBO_GATE.bandMemo[k] = e\n"
    "\tend\n"
    "\treturn e\n"
    "end\n"
    "TURBO_GATE.get = function(initData)\n"
    "\tif not TURBO_GATE.enabled or TURBO_FACES_GATE_OFF == true then return nil end\n"
    "\treturn TURBO_GATE.band(initData) or TURBO_GATE.entries[initData.PlayerId]\n"
    "end\n"
    "TURBO_GATE.inList = function(list, v)\n"
    "\tlocal lo, hi = 1, #list // 2\n"
    "\twhile lo <= hi do\n"
    "\t\tlocal mid = (lo + hi) // 2\n"
    "\t\tif v < list[2 * mid - 1] then hi = mid - 1\n"
    "\t\telseif v > list[2 * mid] then lo = mid + 1\n"
    "\t\telse return true end\n"
    "\tend\n"
    "\treturn false\n"
    "end\n"
    "TURBO_GATE.resolve = function(v, code, list, fallback, initData)\n"
    "\tif v ~= TURBO_GATE.DB then return v end\n"
    "\tif type(code) == \"number\" and code >= 1 and initData.HairStyle == 0 and TURBO_GATE.inList(list, code) then return code end\n"
    "\treturn fallback\n"
    "end\n"
    "TURBO_GATE.hairId = function(initData)\n"
    "\tlocal e = TURBO_GATE.get(initData)\n"
    "\tif e == nil or e.hair == nil then return nil end\n"
    "\treturn TURBO_GATE.resolve(e.hair, initData.Hair, TURBO_GATE.okHair, e.hf, initData)\n"
    "end\n"
    "TURBO_GATE.beardId = function(initData)\n"
    "\tlocal e = TURBO_GATE.get(initData)\n"
    "\tif e == nil or e.beard == nil then return nil end\n"
    "\treturn TURBO_GATE.resolve(e.beard, initData.FacialHairType, TURBO_GATE.okBeard, e.bf, initData)\n"
    "end\n"
    "TURBO_GATE.hairColours = function(initData)\n"
    "\tlocal e = TURBO_GATE.get(initData)\n"
    "\treturn (e ~= nil and e.hc == true and TURBO_GATE.hairId(initData) ~= nil) or nil\n"
    "end\n"
    "TURBO_GATE.strandBeardId = function(initData)\n"
    "\treturn (initData.HeadClass == 0 and TURBO_GATE.beardId(initData)) or nil\n"
    "end\n"
    "TURBO_GATE.facialHairColours = function(initData)\n"
    "\tlocal e = TURBO_GATE.get(initData)\n"
    "\tif e == nil then return nil end\n"
    "\tif e.hc == true and TURBO_GATE.hairId(initData) ~= nil then return true end\n"
    "\treturn (e.bc == true and initData.HeadClass == 0 and TURBO_GATE.beardId(initData) ~= nil) or nil\n"
    "end\n"
    "-- ===== END TURBO PER-PLAYER FACE GATE v4 =====\n"
    "--@@GATE-END\n";

